<?php
/**
 * Zero-dependency assertion runner for the generated data/bots.php.
 * Run: php tests/test-bot-signatures.php
 *
 * The file is generated by build/generate-bots.php. A pattern that fails to
 * compile makes preg_match() return false, which classify() reads as "no
 * match", so a broken regenerate would quietly let every bot through as a
 * visitor. This compiles each category exactly as classify() does.
 */

if ( ! defined( 'ABSPATH' ) ) {
	define( 'ABSPATH', __DIR__ );
}
if ( ! defined( 'VIREO_DIR' ) ) {
	define( 'VIREO_DIR', dirname( __DIR__ ) . '/' );
}

require __DIR__ . '/../includes/class-bot-filter.php';

use VireoAnalytics\Bot_Filter;

$fail = 0;
function ok( $cond, $msg ) {
	global $fail;
	if ( $cond ) {
		echo "  ok  $msg\n";
	} else {
		echo "  FAIL  $msg\n";
		$fail++;
	}
}

$file = VIREO_DIR . 'data/bots.php';
$out  = [];
exec( escapeshellarg( PHP_BINARY ) . ' -l ' . escapeshellarg( $file ) . ' 2>&1', $out, $code );
ok( 0 === $code, 'data/bots.php parses' );

$data = require $file;
ok( is_array( $data ) && count( $data ) >= 5, 'it returns the category map (' . ( is_array( $data ) ? count( $data ) : 0 ) . ' categories)' );

$known = [ 'ai', 'uptime', 'social', 'search', 'archive', 'automation', 'other' ];
foreach ( (array) $data as $key => $pattern ) {
	ok( in_array( $key, $known, true ), "$key is a category the dashboard knows" );
	ok( is_string( $pattern ) && '' !== $pattern, "$key has a pattern" );
	ok( false !== @preg_match( Bot_Filter::extended_regex( (string) $pattern ), '' ), "$key compiles" . ( preg_last_error() ? ': ' . preg_last_error_msg() : '' ) );
}

// The last ai entry still lands in ai, so the pattern wasn't cut short: a
// stray quote or delimiter would end it early.
ok( 'ai' === Bot_Filter::classify( 'Mozilla/5.0 (compatible; WRTNBot/1.0)', [] ), 'an entry from the end of the ai list still lands in ai' );

// Regenerating without an argument must reproduce this file, so the commit in
// its header has to be the one the generator pins.
$header = (string) file_get_contents( $file );
$gen    = (string) file_get_contents( VIREO_DIR . 'build/generate-bots.php' );
preg_match( '/at commit ([0-9a-f]{40})/', $header, $in_file );
preg_match( "/PINNED_REF = '([0-9a-f]{40})'/", $gen, $pinned );
ok( isset( $in_file[1], $pinned[1] ) && $in_file[1] === $pinned[1], 'the header records the commit the generator pins' );

echo $fail ? "\n$fail failed\n" : "\nall passed\n";
exit( $fail ? 1 : 0 );
